package com.example.academic;
import static org.junit.jupiter.api.Assertions.*;
import com.example.academic.student.*;
import com.example.academic.branch.*;
import com.example.academic.course.*;
import com.example.academic.room.*;
import com.example.academic.schoolclass.*;
import com.example.academic.enrollment.*;
import com.example.academic.session.*;
import com.example.academic.attendance.*;
import com.example.academic.security.*;
import com.example.academic.common.*;
import jakarta.persistence.EntityManager;
import java.time.*;
import java.math.BigDecimal;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.context.SecurityContextHolder;
@SpringBootTest(properties="spring.datasource.url=jdbc:h2:mem:student-learning;MODE=MySQL;DB_CLOSE_DELAY=-1") @Transactional
class StudentLearningTest {
 @Autowired StudentAccess studentAccess;
 @Test void documentScopesKeepHistoryButRejectCancelledBeforeLearning(){var historic=enroll(own,Enrollment.StudyStatus.COMPLETED);var cancelled=enroll(own,Enrollment.StudyStatus.DROPPED);var foreign=enroll(other,Enrollment.StudyStatus.STUDYING);flush();assertTrue(studentAccess.documents(null).stream().anyMatch(s->s.enrollmentId().equals(historic.getId())));assertTrue(studentAccess.documents(cancelled.getId()).isEmpty());assertThrows(ApiException.class,()->studentAccess.documents(foreign.getId()));period(cancelled,today.minusDays(2),today);flush();assertEquals(1,studentAccess.documents(cancelled.getId()).size());}
 @Autowired StudentProgressService progress;
 @Test void attendanceAndSourceRequireOwnedEnrollment(){var foreign=enroll(other,Enrollment.StudyStatus.STUDYING);flush();assertThrows(ApiException.class,()->progress.attendance(foreign.getId(),0,20,null,null));assertThrows(ApiException.class,()->progress.source(foreign.getId()));var ownEnrollment=enroll(own,Enrollment.StudyStatus.STUDYING);flush();actor(own,Role.ADMIN);assertThrows(ApiException.class,()->progress.source(ownEnrollment.getId()));}
 @Test void attendanceQueryExcludesFutureScheduledAndCancelled(){var e=enroll(own,Enrollment.StudyStatus.STUDYING);period(e,today.minusDays(7),null);session(today.minusDays(1),ClassSession.Status.COMPLETED);session(today,ClassSession.Status.SCHEDULED);session(today.minusDays(2),ClassSession.Status.CANCELLED);session(today.plusDays(1),ClassSession.Status.COMPLETED);flush();var r=progress.attendance(e.getId(),0,20,null,null);assertEquals(1,r.totalElements());assertEquals(1,r.summary().notRecorded());assertNull(r.summary().attendancePercent());}
 @Autowired EntityManager em;@Autowired StudentLearningService service;
 Student own,other;SchoolClass school;Branch branch;LocalDate today=LocalDate.now(BusinessTime.ZONE);
 @BeforeEach void setup(){branch=new Branch();branch.setCode("STU-G4");branch.setName("Branch");branch.setPhone("0900000000");em.persist(branch);var course=new Course();course.setCode("G4");course.setName("English");course.setMaxStudents(30);course.setTuitionFee(BigDecimal.TEN);em.persist(course);var room=new Room();room.setCode("R4");room.setName("Room4");room.setCapacity(30);room.setBranchId(branch.getId());em.persist(room);school=new SchoolClass();school.setCode("C4");school.setName("Class4");school.setCourse(course);school.setRoom(room);school.setTeacherId(1L);school.setTeacherName("Teacher");school.setBranchId(branch.getId());school.setStartDate(today.minusDays(20));school.setEndDate(today.plusDays(30));school.setMaxSize(30);school.setSessionsInitialized(true);em.persist(school);own=student(501L,"Own");other=student(502L,"Other");actor(own,Role.STUDENT);}
 @AfterEach void clear(){SecurityContextHolder.clearContext();}
 Student student(Long account,String name){var s=new Student();s.setFullName(name);s.setPhone("0900000000");s.setBranchId(branch.getId());s.setAccountId(account);em.persist(s);return s;}
 void actor(Student s,Role role){SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(new CurrentUser(s.getAccountId(),s.getId(),999L,role,"student",List.of()),null,List.of()));}
 Enrollment enroll(Student s,Enrollment.StudyStatus status){var e=new Enrollment();e.setStudent(s);e.setSchoolClass(school);e.setStudyStatus(status);e.setEnrolledAt(today.minusDays(10).atStartOfDay());em.persist(e);return e;}
 void period(Enrollment e,LocalDate from,LocalDate until){var p=new EnrollmentPeriod();p.setEnrollment(e);p.setActiveFrom(from);p.setActiveUntil(until);em.persist(p);}
 ClassSession session(LocalDate date,ClassSession.Status status){var s=new ClassSession();s.setSchoolClass(school);s.setSessionDate(date);s.setStartTime(LocalTime.of(8,0));s.setEndTime(LocalTime.of(9,30));s.setRoomName("Room4");s.setTeacherId(2L);s.setTeacherName("Substitute");s.setPlannedTeacherId(1L);s.setPlannedTeacherName("Teacher");s.setStatus(status);em.persist(s);return s;}
 void flush(){em.flush();em.clear();}
 @Test void listGroupsAndOwnership(){var a=enroll(own,Enrollment.StudyStatus.STUDYING);var b=enroll(own,Enrollment.StudyStatus.RESERVED);var c=enroll(own,Enrollment.StudyStatus.TRANSFERRED);var foreign=enroll(other,Enrollment.StudyStatus.STUDYING);flush();assertEquals(2,service.enrollments(0,1,StudentLearningService.Group.CURRENT,null).totalElements());assertEquals(2,service.enrollments(0,1,StudentLearningService.Group.CURRENT,null).totalPages());assertEquals(1,service.enrollments(0,20,StudentLearningService.Group.HISTORY,null).totalElements());assertThrows(ApiException.class,()->service.detail(foreign.getId()));assertEquals(a.getId(),service.detail(a.getId()).enrollment().id());}
 @Test void exclusiveEndAndPauseGap(){var e=enroll(own,Enrollment.StudyStatus.STUDYING);period(e,today.minusDays(7),today.minusDays(3));period(e,today,null);var before=session(today.minusDays(8),ClassSession.Status.COMPLETED);var allowed=session(today.minusDays(7),ClassSession.Status.COMPLETED);var paused=session(today.minusDays(3),ClassSession.Status.COMPLETED);var returned=session(today,ClassSession.Status.SCHEDULED);flush();var ids=service.schedule(today.minusDays(9),today.plusDays(1),null,0,20).content().stream().map(StudentLearningService.SessionView::sessionId).toList();assertEquals(List.of(allowed.getId(),returned.getId()),ids);assertThrows(ApiException.class,()->service.session(before.getId()));assertThrows(ApiException.class,()->service.session(paused.getId()));}
 @Test void transferredKeepsHistoryButNotFuture(){var e=enroll(own,Enrollment.StudyStatus.TRANSFERRED);period(e,today.minusDays(7),today);var past=session(today.minusDays(1),ClassSession.Status.COMPLETED);session(today,ClassSession.Status.SCHEDULED);flush();assertEquals(List.of(past.getId()),service.schedule(today.minusDays(8),today.plusDays(1),e.getId(),0,20).content().stream().map(StudentLearningService.SessionView::sessionId).toList());}
 @Test void cancelledMakeupAndDuplicateEnrollments(){var e=enroll(own,Enrollment.StudyStatus.STUDYING);var second=enroll(own,Enrollment.StudyStatus.STUDYING);period(e,today,null);period(second,today,null);var cancelled=session(today,ClassSession.Status.CANCELLED);var makeup=session(today.plusDays(1),ClassSession.Status.SCHEDULED);makeup.setKind(ClassSession.Kind.MAKEUP);makeup.setMakeupForId(cancelled.getId());flush();var list=service.schedule(today,today.plusDays(2),null,0,1);assertEquals(2,list.totalElements());assertEquals(2,list.totalPages());assertEquals(2,list.content().getFirst().enrollmentIds().size());var next=service.schedule(today,today.plusDays(2),null,1,1).content().getFirst();assertTrue(next.isMakeup());assertTrue(next.teacherChanged());assertEquals("Substitute",next.teacherName());assertEquals(1,service.schedule(today,today.plusDays(2),second.getId(),1,1).content().getFirst().enrollmentIds().size());}
 @Test void makeupOutsidePeriodIsNotInferred(){var e=enroll(own,Enrollment.StudyStatus.RESERVED);period(e,today.minusDays(7),today);var original=session(today.minusDays(1),ClassSession.Status.CANCELLED);var makeup=session(today.plusDays(1),ClassSession.Status.SCHEDULED);makeup.setKind(ClassSession.Kind.MAKEUP);makeup.setMakeupForId(original.getId());flush();assertThrows(ApiException.class,()->service.session(makeup.getId()));assertEquals(1,service.schedule(today.minusDays(7),today.plusDays(2),null,0,20).totalElements());}
 @Test void legacyActiveAndRecordedTerminalHistory(){var legacy=enroll(own,Enrollment.StudyStatus.STUDYING);var row=session(today.minusDays(1),ClassSession.Status.COMPLETED);flush();assertTrue(service.session(row.getId()).legacyEstimated());assertEquals("LEGACY_ESTIMATED",service.detail(legacy.getId()).coverage());}
 @Test void terminalLegacyRequiresExactSessionRecord(){var terminal=enroll(own,Enrollment.StudyStatus.COMPLETED);var row=session(today.minusDays(1),ClassSession.Status.COMPLETED);var hidden=session(today.minusDays(2),ClassSession.Status.COMPLETED);var a=new Attendance();a.setEnrollment(terminal);a.setClassSession(row);a.setSessionDate(row.getSessionDate());a.setStatus(Attendance.Status.PRESENT);a.setRecordedBy(1L);a.setRecordedByName("Staff");em.persist(a);flush();assertEquals("LEGACY_UNVERIFIED",service.detail(terminal.getId()).coverage());assertEquals(row.getId(),service.session(row.getId()).sessionId());assertThrows(ApiException.class,()->service.session(hidden.getId()));}
 @Test void foreignFilterAndInvalidWindowsRejected(){var foreign=enroll(other,Enrollment.StudyStatus.STUDYING);flush();assertThrows(ApiException.class,()->service.schedule(today,today,foreign.getId(),0,20));assertThrows(ApiException.class,()->service.schedule(today,today.plusDays(92),null,0,20));assertThrows(ApiException.class,()->service.schedule(today,today.minusDays(1),null,0,20));assertThrows(ApiException.class,()->service.enrollments(Integer.MAX_VALUE,100,StudentLearningService.Group.ALL,null));actor(own,Role.ADMIN);assertThrows(ApiException.class,()->service.next());}
 @Test void nextSkipsCancelledUnknownAndForeign(){var e=enroll(own,Enrollment.StudyStatus.STUDYING);period(e,today,null);session(today.plusDays(1),ClassSession.Status.CANCELLED);var unknown=session(today.plusDays(1),ClassSession.Status.SCHEDULED);unknown.setStartTime(null);unknown.setEndTime(null);var expected=session(today.plusDays(2),ClassSession.Status.SCHEDULED);flush();assertEquals(expected.getId(),service.next().session().sessionId());assertEquals("Asia/Ho_Chi_Minh",service.next().timezone());}
 @Test void noEnrollmentReturnsEmptyNotInvented(){session(today.plusDays(1),ClassSession.Status.SCHEDULED);flush();assertNull(service.next().session());assertEquals(0,service.schedule(today,today.plusDays(2),null,0,20).totalElements());}
}
